/**
 * The Parshwanath Infra logo (05 Sheltering Arch): the seven-lobed arch on its otla and, beside it, the name. Outlines
 * come from logo-data.ts (generated by brand/logo/_build; no font needed). Drawn in currentColor, so it follows the
 * text colour through every tone and theme. The height is the --logo-h custom property (default 2.5rem): the mark and
 * the name are two SVGs of that one height, which keeps the lockup's alignment at any size. Decorative unless `label`
 * is given (a link or heading next to it usually carries the name). Pure SVG, no client code.
 */
import { cn } from "./cn";
import { LOGO_GAP, LOGO_MARK, LOGO_WORD, type LogoShape } from "./logo-data";

interface LogoProps {
  /** Accessible name. Omit when the surrounding link or heading already names the company. */
  label?: string;
  /** Show the name beside the mark: always, never, or from the sm breakpoint up. */
  wordmark?: boolean | "sm";
  className?: string;
  /** Classes for the mark alone, for example an accent colour. */
  markClassName?: string;
}

/** A length in em, rounded so the style attribute stays short (0.849em, not 0.8490000000000001em). */
function em(value: number): string {
  return `${Math.round(value * 10000) / 10000}em`;
}

function Shape({ shape, className, gap = 0 }: { shape: LogoShape; className?: string; gap?: number }) {
  return (
    <svg
      viewBox={`0 0 ${shape.width} 100`}
      aria-hidden="true"
      focusable="false"
      className={className}
      style={{ width: em(shape.width / 100), height: "1em", marginLeft: gap ? em(gap) : undefined }}
    >
      <path d={shape.d} fill="currentColor" />
    </svg>
  );
}

export function Logo({ label, wordmark = true, className, markClassName }: LogoProps) {
  const a11y = label ? ({ role: "img", "aria-label": label } as const) : ({ "aria-hidden": true } as const);
  return (
    <span className={cn("logo", className)} {...a11y}>
      <Shape shape={LOGO_MARK} className={markClassName} />
      {wordmark ? (
        <Shape shape={LOGO_WORD} gap={LOGO_GAP} className={wordmark === "sm" ? "hidden sm:block" : undefined} />
      ) : null}
    </span>
  );
}
